                        kx = XaA(scr, nn, kk, x);
                        ky = XaA(scr, nn, kk, y);
                        if (kx <= ky) {
                            XaAs(scr, nn, 7, o, x);
                            p += 1;
                        } else {
                            XaAs(scr, nn, 7, o, y);
                            q += 1;
                        }
                    }
                    o += 1;
                }
                start += 2 * width;
            }
            p = 0;
            while (p < cnt) {
                x = XaA(scr, nn, 7, p);
                XaAs(scr, nn, arr, lo + p, x);
                p += 1;
            }
            width *= 2;
        }
        return 0;
    }
    internal static int XaCell(int x, int size) {
        // The grid cell (0..63) of a coordinate on a page `size` wide.
        int v = (int) (unchecked(((long) x) * ((long) 64)) / ((long) size));
        if (v < 0) {
            v = 0;
        }
        if (v > 63) {
            v = 63;
        }
        return v;
    }
    internal static int XaGridAdd(emon.Port.Cells scr, int nn, emon.Port.Cells gp, int node, int pw, int ph) {
        // Enter a node in every grid cell its box touches.
        int cx0 = XaCell(XaHb(scr, node, 0), pw);
        int cx1 = XaCell(XaHb(scr, node, 2), pw);
        int cy0 = XaCell(XaHb(scr, node, 1), ph);
        int cy1 = XaCell(XaHb(scr, node, 3), ph);
        int gb = XaGridBase(nn);
        int cy = cy0;
        int cx = 0;
        int at = 0;
        int head = 0;
        int at2 = 0;
        while (cy <= cy1) {
            cx = cx0;
            while (cx <= cx1) {
                at = gb + ((cy * 64) + cx);
                head = emon.Port.CellsAt(scr, at);
                emon.Port.CellsPush(gp, node);
                emon.Port.CellsPush(gp, head);
                at2 = emon.Port.CellsLen(gp) - 2;
                emon.Port.CellsSet(scr, at, at2);
                cx += 1;
            }
            cy += 1;
        }
        return 0;
    }
    internal static int XaBest(emon.Port.Cells scr, int nn, emon.Port.Cells gp, int nt, int node, int pw, int ph, int side) {
        // The candidate of `node` with the most overlap (`ev-overlap-small`), -1 for none; ties go to the earlier node. `side` 1 looks
        // among the text layer's candidates, 0 among the OCR words (other than the node itself).
        int cx0 = XaCell(XaHb(scr, node, 0), pw);
        int cx1 = XaCell(XaHb(scr, node, 2), pw);
        int cy0 = XaCell(XaHb(scr, node, 1), ph);
        int cy1 = XaCell(XaHb(scr, node, 3), ph);
        int gb = XaGridBase(nn);
        int cy = cy0;
        int cx = 0;
        int e = 0;
        int k = 0;
        int ov = 0;
        int best = -1;
        int bestov = 0;
        while (cy <= cy1) {
            cx = cx0;
            while (cx <= cx1) {
                e = emon.Port.CellsAt(scr, gb + ((cy * 64) + cx));
                while (e >= 0) {
                    k = emon.Port.CellsAt(gp, e);
                    if (((side == 1) && ((k < nt) && (XaHb(scr, k, 9) != 0))) || ((side == 0) && ((k >= nt) && (k != node)))) {
                        if (XaNodeCand(scr, node, k) == 1) {
                            ov = Evidence.EvOverlapSmall(XaHb(scr, node, 0), XaHb(scr, node, 1), XaHb(scr, node, 2), XaHb(scr, node, 3), XaHb(scr, k, 0), XaHb(scr, k, 1), XaHb(scr, k, 2), XaHb(scr, k, 3));
                            if ((ov > bestov) || ((ov == bestov) && ((best >= 0) && (k < best)))) {
                                bestov = ov;
                                best = k;
                            }
                        }
                    }
                    e = emon.Port.CellsAt(gp, e + 1);
                }
                cx += 1;
            }
            cy += 1;
        }
        return best;
    }
    internal static int XaAttach(emon.Port.Cells scr, int nn, emon.Port.Cells gp, int nt, int no, int pw, int ph, emon.Port.Cells etext, emon.Port.Cells feats, emon.Port.Cells ta, emon.Port.Cells tb, emon.Port.Cells tt) {
        // What no step matched but a word of the other source COVERS: an OCR word that is a candidate of a text-layer word (the
        // word is longer than the pairing steps reach: `Section2.1` read as three words, a whole line whose spaces the font
        // does not map) joins that word's group as a split, and a text-layer word that is a candidate of an OCR word joins its
        // group as a merged one. Without this the covered words would be OCR-only or text-only groups of their own, and
        // arbitration (P7.3) would write the same text twice (D279).
        int j = nt;
        int k = 0;
        int layer = 0;
        int sim = 0;
        int cur = 0;
        while (j < (nt + no)) {
            if (XaA(scr, nn, 4, j) == 0) {
                k = XaBest(scr, nn, gp, nt, j, pw, ph, 1);
                if (k >= 0) {
                    XaUnion(scr, nn, k, j);
                    XaAs(scr, nn, 4, j, 1);
                    cur = XaA(scr, nn, 1, k);
                    XaAs(scr, nn, 1, k, cur | 4);
                    cur = XaA(scr, nn, 1, j);
                    XaAs(scr, nn, 1, j, cur | 4);
                    XaAs(scr, nn, 11, 0, k);
                    XaAs(scr, nn, 13, 0, j);
                    sim = XaSim(scr, nn, 11, 0, 1, 13, 0, 1, etext, 0, ta, tb, tt);
                    layer = 1;
                    if (XaHb(scr, k, 9) == 2) {
                        layer = 2;
                    }
                    if (layer == 1) {
                        XaPut(scr, j, Evidence.XoSimText(), sim, feats);
                    }
                    if (layer == 2) {
                        XaPut(scr, j, Evidence.XoSimHidden(), sim, feats);
                    }
                }
            }
            j += 1;
        }
        k = 0;
        while (k < nt) {
            if ((XaHb(scr, k, 9) != 0) && (XaA(scr, nn, 4, k) == 0)) {
                j = XaBest(scr, nn, gp, nt, k, pw, ph, 0);
                if (j >= 0) {
                    XaUnion(scr, nn, k, j);
                    XaAs(scr, nn, 4, k, 1);
                    cur = XaA(scr, nn, 1, k);
                    XaAs(scr, nn, 1, k, cur | 8);
                    cur = XaA(scr, nn, 1, j);
                    XaAs(scr, nn, 1, j, cur | 8);
                }
            }
            k += 1;
        }
        return 0;
    }
    internal static int XaCluster(emon.Port.Cells scr, int nn, emon.Port.Cells gp, int nt, int no, int pw, int ph) {
        // Join the OCR words no step matched with the overlapping OCR words of other runs.
        int gb = XaGridBase(nn);
        int j = nt;
        int cx = 0;
        int cy = 0;
        int cx0 = 0;
        int cx1 = 0;
        int cy1 = 0;
        int e = 0;
        int k = 0;
        while (j < (nt + no)) {
            if (XaA(scr, nn, 4, j) == 0) {
                cx0 = XaCell(XaHb(scr, j, 0), pw);
                cx1 = XaCell(XaHb(scr, j, 2), pw);
                cy = XaCell(XaHb(scr, j, 1), ph);
                cy1 = XaCell(XaHb(scr, j, 3), ph);
                while (cy <= cy1) {
                    cx = cx0;
                    while (cx <= cx1) {
                        e = emon.Port.CellsAt(scr, gb + ((cy * 64) + cx));
                        while (e >= 0) {
                            k = emon.Port.CellsAt(gp, e);
                            if ((k >= nt) && (k != j)) {
                                if (XaHb(scr, k, 11) != XaHb(scr, j, 11)) {
                                    if (XaNodeCand(scr, j, k) == 1) {
                                        XaUnion(scr, nn, j, k);
                                    }
                                }
                            }
                            e = emon.Port.CellsAt(gp, e + 1);
                        }
                        cx += 1;
                    }
                    cy += 1;
                }
            }
            j += 1;
        }
        return 0;
    }
    internal static int XaPos(emon.Port.Cells scr, int node, int rot, int dir) {
        // A node's position along a line whose baseline is at `rot`: the centre projected on the reading axis, negated for a
        // right-to-left line (so every line is read in logical order).
        long cx = (long) (XaHb(scr, node, 0) + XaHb(scr, node, 2));
        long cy = (long) (XaHb(scr, node, 1) + XaHb(scr, node, 3));
        long v = unchecked(cx * ((long) Evidence.EvCos(rot))) - unchecked(cy * ((long) Evidence.EvSin(rot)));
        int p = (int) (v / ((long) 131072));
        if (dir == 1) {
            return 0 - p;
        }
        return p;
    }
    internal static int XaExtent(emon.Port.Cells scr, int nn, int node, int rot, int pos) {
        // Set node's extent along a line at `rot` (array 14 its start, 15 its end): its position `pos` less and plus the half of
        // its box projected on the line's axis.
        long w = (long) (XaHb(scr, node, 2) - XaHb(scr, node, 0));
        long h = (long) (XaHb(scr, node, 3) - XaHb(scr, node, 1));
        int c = Evidence.EvCos(rot);
        int sn = Evidence.EvSin(rot);
        if (c < 0) {
            c = 0 - c;
        }
        if (sn < 0) {
            sn = 0 - sn;
        }
        int e = (int) (unchecked(unchecked(w * ((long) c)) + unchecked(h * ((long) sn))) / ((long) 131072));
        XaAs(scr, nn, 14, node, pos - e);
        XaAs(scr, nn, 15, node, pos + e);
        return 0;
    }
    internal static int XaRunLines(emon.Port.Cells scr, int nn, int nt, int na, int nruns, emon.Port.Cells etext, emon.Port.Cells feats, emon.Port.Cells dp, emon.Port.Cells ta, emon.Port.Cells tb, emon.Port.Cells tt) {
        // Every text-layer line: its OCR words (`ord[0, na)` is the assigned ones sorted by line), then the passes.
        int i = 0;
        int a = 0;
        int b = 0;
        int lid = 0;
        int lo = 0;
        int hi = 0;
        int mid = 0;
        int bc = 0;
        int t = 0;
        int node = 0;
        int rot = 0;
        int dir = 0;
        int layer = 0;
        int n = 0;
        int rank = 0;
        int m = 0;
        int pos = 0;
        int ol = 0;
        while (i < nt) {
            if (XaHb(scr, i, 9) == 0) {
                i += 1;
            } else {
                a = i;
                lid = XaHb(scr, i, 10);
                b = i + 1;
                // the run goes on over the words with the same line, skipping the ones that are not candidates
                t = i + 1;
                while ((t < nt) && ((XaHb(scr, t, 9) == 0) || (XaHb(scr, t, 10) == lid))) {
                    if (XaHb(scr, t, 9) != 0) {
                        b = t + 1;
                    }
                    t += 1;
                }
                rot = XaHb(scr, a, 4);
                dir = XaHb(scr, a, 5);
                // the line's OCR block: ord is sorted by oline, so find its first and its count
                lo = 0;
                hi = na;
                while (lo < hi) {
                    mid = (lo + hi) / 2;
                    node = XaA(scr, nn, 6, mid);
                    ol = XaA(scr, nn, 2, node);
                    if (ol < lid) {
                        lo = mid + 1;
                    } else {
                        hi = mid;
                    }
                }
                bc = 0;
                ol = lid;
                while (((lo + bc) < na) && (ol == lid)) {
                    node = XaA(scr, nn, 6, lo + bc);
                    ol = XaA(scr, nn, 2, node);
                    if (ol == lid) {
                        bc += 1;
                    }
                }
                t = 0;
                while (t < bc) {
                    node = XaA(scr, nn, 6, lo + t);
                    XaAs(scr, nn, 12, t, node);
                    pos = XaPos(scr, node, rot, dir);
                    XaAs(scr, nn, 5, node, pos);
                    XaExtent(scr, nn, node, rot, pos);
                    t += 1;
                }
                t = a;
                while (t < b) {
                    pos = XaPos(scr, t, rot, dir);
                    XaAs(scr, nn, 5, t, pos);
                    XaExtent(scr, nn, t, rot, pos);
                    t += 1;
                }
                if (bc > 1) {
                    XaMsort(scr, nn, 12, 0, bc, 5);
                }
                layer = 1;
                while (layer <= 2) {
                    n = 0;
                    t = a;
                    while (t < b) {
                        if (XaHb(scr, t, 9) == layer) {
                            XaAs(scr, nn, 11, n, t);
                            n += 1;
                        }
                        t += 1;
                    }
                    if ((n > 0) && (bc > 0)) {
                        rank = 0;
                        while (rank < nruns) {
                            m = 0;
                            t = 0;
                            while (t < bc) {
                                node = XaA(scr, nn, 12, t);
                                if (XaA(scr, nn, 3, node) == rank) {
                                    XaAs(scr, nn, 13, m, node);
                                    m += 1;
                                }
                                t += 1;
                            }
                            if (m > 0) {
                                XaAlign(scr, nn, n, m, layer, rank, etext, feats, dp, ta, tb, tt);
                            }
                            rank += 1;
                        }
                    }
                    layer += 1;
                }
                i = b;
            }
        }
        return 0;
    }
    internal static int XaEmit(int page, emon.Port.Cells scr, int nn, int nt, int no, int w0, int o0, int t0, int t1, emon.Port.Cells tlines, emon.Port.Cells etext, emon.Port.Cells refs, emon.Port.Cells cg, emon.Port.Cells ta, emon.Port.Cells tb, emon.Port.Cells tt) {
        // Write the groups in the order of their first candidate; answers how many.
        int total = nt + no;
        int i = 0;
        int s = 0;
        int g = 0;
        int r = 0;
        int c = 0;
        int e = 0;
        int node = 0;
        int tcnt = 0;
        int hcnt = 0;
        int ocnt = 0;
        int x0 = 0;
        int y0 = 0;
        int x1 = 0;
        int y1 = 0;
        int rot = 0;
        int flags = 0;
        int minrank = 0;
        int nm = 0;
        int row = 0;
        int bestov = 0;
        int best = 0;
        int ov = 0;
        int kind = 0;
        int sim = -1;
        int simfold = -1;
        // roots, counts, the exclusive scan and the members bucketed by root (stable, so in candidate order)
        i = 0;
        while (i < nn) {
            XaAs(scr, nn, 8, i, 0);
            i += 1;
        }
        i = 0;
        while (i < total) {
            r = XaFind(scr, nn, i);
            XaAs(scr, nn, 10, i, r);
            if (XaHb(scr, i, 9) != 0) {
                c = XaA(scr, nn, 8, r);
                XaAs(scr, nn, 8, r, c + 1);
            }
            i += 1;
        }
        s = 0;
        i = 0;
        while (i < total) {
            c = XaA(scr, nn, 8, i);
            XaAs(scr, nn, 8, i, s);
            XaAs(scr, nn, 7, i, s);
            s += c;
            i += 1;
        }
        XaAs(scr, nn, 8, total, s);
        i = 0;
        while (i < total) {
            if (XaHb(scr, i, 9) != 0) {
                r = XaA(scr, nn, 10, i);
                c = XaA(scr, nn, 7, r);
                XaAs(scr, nn, 9, c, i);
                XaAs(scr, nn, 7, r, c + 1);
            }
            i += 1;
        }
        r = 0;
        while (r < total) {
            if ((XaHb(scr, r, 9) != 0) && (XaA(scr, nn, 10, r) == r)) {
                s = XaA(scr, nn, 8, r);
                e = XaA(scr, nn, 8, r + 1);
                tcnt = 0;
                hcnt = 0;
                ocnt = 0;
                flags = 0;
                i = s;
                while (i < e) {
                    node = XaA(scr, nn, 9, i);
                    kind = XaHb(scr, node, 9);
                    if (kind == 1) {
                        XaAs(scr, nn, 11, tcnt, node);
                        tcnt += 1;
                    }
                    if (kind == 2) {
                        XaAs(scr, nn, 13, hcnt, node);
                        hcnt += 1;
                    }
                    if (kind == 3) {
                        XaAs(scr, nn, 12, ocnt, node);
                        ocnt += 1;
                    }
                    if (i == s) {
                        x0 = XaHb(scr, node, 0);
                        y0 = XaHb(scr, node, 1);
                        x1 = XaHb(scr, node, 2);
                        y1 = XaHb(scr, node, 3);
                        rot = XaHb(scr, node, 4);
                    } else {
                        if (XaHb(scr, node, 0) < x0) {
                            x0 = XaHb(scr, node, 0);
                        }
                        if (XaHb(scr, node, 1) < y0) {
                            y0 = XaHb(scr, node, 1);
                        }
                        if (XaHb(scr, node, 2) > x1) {
                            x1 = XaHb(scr, node, 2);
                        }
                        if (XaHb(scr, node, 3) > y1) {
                            y1 = XaHb(scr, node, 3);
                        }
                    }
                    c = XaA(scr, nn, 1, node);
                    flags |= c;
                    i += 1;
                }
                c = XaA(scr, nn, 11, 0);
                e = XaA(scr, nn, 13, 0);
                node = XaA(scr, nn, 12, 0);
                if (tcnt > 0) {
                    rot = XaHb(scr, c, 4);
                }
                if ((tcnt == 0) && (hcnt > 0)) {
                    rot = XaHb(scr, e, 4);
                }
                if ((tcnt == 0) && ((hcnt == 0) && (ocnt > 0))) {
                    rot = XaHb(scr, node, 4);
                }
                if (((tcnt + hcnt) > 0) && (ocnt == 0)) {
                    flags |= Player.PlgTextOnly();
                }
                if ((ocnt > 0) && ((tcnt + hcnt) == 0)) {
                    flags |= Player.PlgOcrOnly();
                }
                row = Player.CgNew(cg, page, x0, y0, x1, y1, rot);
                Player.CgSet(cg, row, Player.CgfFlags(), flags);
                if (tcnt > 0) {
                    Player.CgSet(cg, row, Player.CgfTfirst(), Evidence.RfCount(refs));
                    Player.CgSet(cg, row, Player.CgfTcount(), tcnt);
                    i = 0;
                    while (i < tcnt) {
                        node = XaA(scr, nn, 11, i);
                        Evidence.RfAdd(refs, Evidence.EaWords(), w0 + node);
                        i += 1;
                    }
                }
                if (ocnt > 0) {
                    Player.CgSet(cg, row, Player.CgfOfirst(), Evidence.RfCount(refs));
                    Player.CgSet(cg, row, Player.CgfOcount(), ocnt);
                    i = 0;
                    while (i < ocnt) {
                        node = XaA(scr, nn, 12, i);
                        Evidence.RfAdd(refs, Evidence.EaOwords(), o0 + (node - nt));
                        i += 1;
                    }
                }
                if (hcnt > 0) {
                    Player.CgSet(cg, row, Player.CgfHfirst(), Evidence.RfCount(refs));
                    Player.CgSet(cg, row, Player.CgfHcount(), hcnt);
                    i = 0;
                    while (i < hcnt) {
                        node = XaA(scr, nn, 13, i);
                        Evidence.RfAdd(refs, Evidence.EaWords(), w0 + node);
                        i += 1;
                    }
                }
                // the similarity: the text layer's words (the hidden ones without them) against the lowest run's
                sim = -1;
                simfold = -1;
                if ((ocnt > 0) && ((tcnt + hcnt) > 0)) {
                    node = XaA(scr, nn, 12, 0);
                    minrank = XaA(scr, nn, 3, node);
                    i = 0;
                    while (i < ocnt) {
                        node = XaA(scr, nn, 12, i);
                        c = XaA(scr, nn, 3, node);
                        if (c < minrank) {
                            minrank = c;
                        }
                        i += 1;
                    }
                    nm = 0;
                    i = 0;
                    while (i < ocnt) {
                        node = XaA(scr, nn, 12, i);
                        if (XaA(scr, nn, 3, node) == minrank) {
                            XaAs(scr, nn, 5, nm, node);
                            nm += 1;
                        }
                        i += 1;
                    }
                    if (tcnt > 0) {
                        sim = XaSim(scr, nn, 11, 0, tcnt, 5, 0, nm, etext, 0, ta, tb, tt);
                        simfold = XaSim(scr, nn, 11, 0, tcnt, 5, 0, nm, etext, 1, ta, tb, tt);
                    } else {
                        sim = XaSim(scr, nn, 13, 0, hcnt, 5, 0, nm, etext, 0, ta, tb, tt);
                        simfold = XaSim(scr, nn, 13, 0, hcnt, 5, 0, nm, etext, 1, ta, tb, tt);
                    }
                }
                Player.CgSet(cg, row, Player.CgfSim(), sim);
                Player.CgSet(cg, row, Player.CgfSimfold(), simfold);
                // the tracer line the group's box overlaps most
                best = -1;
                bestov = 0;
                i = t0;
                while (i < t1) {
                    if (XaCand(x0, y0, x1, y1, rot, emon.Port.CellsAt(tlines, (i * 20) + 1), emon.Port.CellsAt(tlines, (i * 20) + 2), emon.Port.CellsAt(tlines, (i * 20) + 3), emon.Port.CellsAt(tlines, (i * 20) + 4), emon.Port.CellsAt(tlines, (i * 20) + 9)) == 1) {
                        ov = Evidence.EvOverlapSmall(x0, y0, x1, y1, emon.Port.CellsAt(tlines, (i * 20) + 1), emon.Port.CellsAt(tlines, (i * 20) + 2), emon.Port.CellsAt(tlines, (i * 20) + 3), emon.Port.CellsAt(tlines, (i * 20) + 4));
                        if (ov > bestov) {
                            bestov = ov;
                            best = i;
                        }
                    }
                    i += 1;
                }
                Player.CgSet(cg, row, Player.CgfTline(), best);
                g += 1;
            }
            r += 1;
        }
        return g;
    }
    internal static int XaLower(emon.Port.Cells c, int stride, int page) {
        // The first row of an arena whose page is at least `page`, the rows being in page order.
        int lo = 0;
        int hi = emon.Port.CellsLen(c) / stride;
        int mid = 0;
        while (lo < hi) {
            mid = (lo + hi) / 2;
            if (emon.Port.CellsAt(c, mid * stride) < page) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        return lo;
    }
    internal static int XaLoadHead(emon.Port.Cells scr, int i, emon.Port.Cells src, int stride, int r) {
        // Copy the head of row r of an arena of the given stride (a word's or an OCR word's) into node i.
        XaHbs(scr, i, 0, emon.Port.CellsAt(src, (r * stride) + Evidence.HdX0()));
        XaHbs(scr, i, 1, emon.Port.CellsAt(src, (r * stride) + Evidence.HdY0()));
        XaHbs(scr, i, 2, emon.Port.CellsAt(src, (r * stride) + Evidence.HdX1()));
        XaHbs(scr, i, 3, emon.Port.CellsAt(src, (r * stride) + Evidence.HdY1()));
        XaHbs(scr, i, 4, emon.Port.CellsAt(src, (r * stride) + Evidence.HdRot()));
        XaHbs(scr, i, 5, emon.Port.CellsAt(src, (r * stride) + Evidence.HdDir()));
        XaHbs(scr, i, 6, emon.Port.CellsAt(src, (r * stride) + Evidence.HdTstart()));
        XaHbs(scr, i, 7, emon.Port.CellsAt(src, (r * stride) + Evidence.HdTlen()));
        XaHbs(scr, i, 8, emon.Port.CellsAt(src, (r * stride) + Evidence.HdFeat()));
        return 0;
    }
    public static int XaPage(int page, emon.Port.Cells epages, emon.Port.Cells words, emon.Port.Cells owords, emon.Port.Cells tlines, emon.Port.Cells feats, emon.Port.Cells etext, emon.Port.Cells refs, emon.Port.Cells cg, emon.Port.Cells scr, emon.Port.Cells gp, emon.Port.Cells dp, emon.Port.Cells ta, emon.Port.Cells tb, emon.Port.Cells tt) {
        // Align one page. See the head of the file. Answers the number of groups appended to `cg`.
        int w0 = XaLower(words, 24, page);
        int w1 = XaLower(words, 24, page + 1);
        int o0 = XaLower(owords, 28, page);
        int o1 = XaLower(owords, 28, page + 1);
        int t0 = XaLower(tlines, 20, page);
        int t1 = XaLower(tlines, 20, page + 1);
        int nt = w1 - w0;
        int no = o1 - o0;
        int total = nt + no;
        int nn = total + 1;
        int erow = Evidence.EvPageRow(epages, page);
        int pw = 1;
        int ph = 1;
        int i = 0;
        int r = 0;
        int f = 0;
        int v = 0;
        int prun = -2;
        int rk = -1;
        int csrc = 0;
        int na = 0;
        if (total == 0) {
            return 0;
        }
        emon.Port.CellsDrop(scr, 0);
        while (i < ((28 * nn) + 4096)) {
            emon.Port.CellsPush(scr, 0);
            i += 1;
        }
        emon.Port.CellsDrop(gp, 0);
        // the text layer's heads, kinds and lines
        i = 0;
        while (i < nt) {
            r = w0 + i;
            XaLoadHead(scr, i, words, 24, r);
            f = XaHb(scr, i, 8);
            v = 0;
            if (f >= 0) {
                v = Evidence.FeGet(feats, f, Evidence.XtVis());
                if (v < 0) {
                    v = 0;
                }
            }
            csrc = emon.Port.CellsAt(words, (r * 24) + Evidence.WfSrc());
            XaHbs(scr, i, 9, 0);
            if ((csrc & Model.SrHiddenText()) != 0) {
                XaHbs(scr, i, 9, 2);
            } else if (v == 0) {
                XaHbs(scr, i, 9, 1);
            }
            f = emon.Port.CellsAt(words, (r * 24) + Evidence.HdLine());
            if (f < 0) {
                f = 1000000000 + i;
            }
            XaHbs(scr, i, 10, f);
            i += 1;
        }
        // the OCR words' heads and their runs, ranked in order of appearance
        i = 0;
        while (i < no) {
            r = o0 + i;
            XaLoadHead(scr, nt + i, owords, 28, r);
            XaHbs(scr, nt + i, 9, 3);
            f = emon.Port.CellsAt(owords, (r * 28) + Evidence.OwfRun());
            XaHbs(scr, nt + i, 11, f);
            if (f != prun) {
                rk += 1;
                prun = f;
            }
            XaAs(scr, nn, 3, nt + i, rk);
            i += 1;
        }
        // the page box (the grid's scale), the union-find and the grid
        i = 0;
        while (i < total) {
            if (XaHb(scr, i, 9) != 0) {
                if (XaHb(scr, i, 2) > pw) {
                    pw = XaHb(scr, i, 2);
                }
                if (XaHb(scr, i, 3) > ph) {
                    ph = XaHb(scr, i, 3);
                }
            }
            XaAs(scr, nn, 0, i, i);
            XaAs(scr, nn, 2, i, -1);
            i += 1;
        }
        if (erow >= 0) {
            v = Evidence.EpGet(epages, erow, Evidence.EpfWidth());
            if (v > 0) {
                pw = v;
            }
            v = Evidence.EpGet(epages, erow, Evidence.EpfHeight());
            if (v > 0) {
                ph = v;
            }
        }
        i = 0;
        while (i < 4096) {
            emon.Port.CellsSet(scr, XaGridBase(nn) + i, -1);
            i += 1;
        }
        i = 0;
        while (i < total) {
            if (XaHb(scr, i, 9) != 0) {
                XaGridAdd(scr, nn, gp, i, pw, ph);
            }
            i += 1;
        }
        // every OCR word's line, and the OCR words that have one sorted by it (stably: by their order)
        i = 0;
        while (i < no) {
            v = XaBest(scr, nn, gp, nt, nt + i, pw, ph, 1);
            if (v >= 0) {
                v = XaHb(scr, v, 10);
            }
            XaAs(scr, nn, 2, nt + i, v);
            if (v >= 0) {
                XaAs(scr, nn, 6, na, nt + i);
                na += 1;
            }
            i += 1;
        }
        if (na > 1) {
            XaMsort(scr, nn, 6, 0, na, 2);
        }
        XaRunLines(scr, nn, nt, na, rk + 1, etext, feats, dp, ta, tb, tt);
        XaAttach(scr, nn, gp, nt, no, pw, ph, etext, feats, ta, tb, tt);
        XaCluster(scr, nn, gp, nt, no, pw, ph);
        return XaEmit(page, scr, nn, nt, no, w0, o0, t0, t1, tlines, etext, refs, cg, ta, tb, tt);
    }
}
